import { chromium } from '/home/wsl/repo/rsmb.tv/node_modules/@playwright/test/index.mjs';
import fs from 'node:fs/promises';
const prefix = '/tmp/rsmb-audit-2026-11-10';
const axeSource = await fs.readFile(prefix + '-axe.min.js', 'utf8');
const browser = await chromium.launch({ headless: true });
const report = { measuredAt: new Date().toISOString(), browser: browser.version(), baseURL: 'https://www.rsmb.tv', notes: 'Unthrottled headless Chromium; reduced motion. Diagnostic scan, not WCAG certification or field performance.', results: [], interactions: {} };
const routes = ['/', '/posts', '/projects', '/about', '/trips/ocean-shores-2024', '/projects/flights/map', '/projects/temperature-records/map', '/projects/tornado-tracks/map', '/projects/adv-atlas/map'];
try {
  for (const width of [390, 1280]) for (const route of routes) {
    const context = await browser.newContext({ viewport: { width, height: 900 }, reducedMotion: 'reduce', serviceWorkers: 'block' });
    await context.route(/https:\/\/(?:cloud|gateway)\.umami\.is\//, r => r.abort());
    await context.addInitScript({ content: axeSource });
    const page = await context.newPage();
    const row = { width, route, errors: [], failedRequests: [] };
    page.on('pageerror', e => row.errors.push(e.message));
    page.on('requestfailed', r => { if (!r.url().includes('umami')) row.failedRequests.push({ url: r.url(), error: r.failure()?.errorText }); });
    try {
      const response = await page.goto(report.baseURL + route, { waitUntil: 'domcontentloaded', timeout: 45000 });
      row.status = response.status();
      await page.waitForSelector('h1,canvas,[role="application"]', { timeout: 30000 });
      await page.waitForTimeout(route.endsWith('/map') ? 7000 : 2000);
      row.dom = await page.evaluate(() => {
        const shown = el => { const b = el.getBoundingClientRect(); const s = getComputedStyle(el); return b.width > 0 && b.height > 0 && s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0'; };
        const targets = [...document.querySelectorAll('button,a[href],input,select,summary,[tabindex="0"]')].filter(shown).map(el => { const b = el.getBoundingClientRect(); return { tag: el.tagName, name: el.getAttribute('aria-label') || el.textContent.trim().slice(0, 90), x: b.x, y: b.y, width: b.width, height: b.height, fontSize: getComputedStyle(el).fontSize }; });
        return { title: document.title, viewportWidth: innerWidth, documentWidth: document.documentElement.scrollWidth, headings: [...document.querySelectorAll('h1,h2,h3')].map(el => ({ tag: el.tagName, text: el.textContent })), mainCount: document.querySelectorAll('main,[role="main"]').length, targetsUnder24: targets.filter(t => t.width < 24 || t.height < 24), targetCount: targets.length, text: document.body.innerText.slice(0, 14000), scripts: performance.getEntriesByType('resource').filter(r => /\.js(?:$|\?)/.test(r.name)).map(r => ({ name: r.name, encodedBodySize: r.encodedBodySize, decodedBodySize: r.decodedBodySize, transferSize: r.transferSize })), mapStates: [...document.querySelectorAll('[data-map-state]')].map(el => ({ testId: el.getAttribute('data-testid'), state: el.getAttribute('data-map-state') })), images: [...document.images].filter(shown).map(el => ({ src: el.currentSrc, complete: el.complete, naturalWidth: el.naturalWidth })) };
      });
      row.screenshot = prefix + '-' + (route.replaceAll('/', '_') || 'home') + '-' + width + '.png';
      await page.screenshot({ path: row.screenshot });
      row.axe = await page.evaluate(async () => {
        const result = await axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa', 'best-practice'] } });
        return { version: result.testEngine.version, passes: result.passes.length, incomplete: result.incomplete.map(v => ({ id: v.id, count: v.nodes.length })), violations: result.violations.map(v => ({ id: v.id, impact: v.impact, description: v.description, helpUrl: v.helpUrl, nodes: v.nodes.map(n => ({ target: n.target, html: n.html, summary: n.failureSummary })) })) };
      });
      if (route === '/about' && width === 1280) {
        const projects = page.locator('header nav').getByRole('link', { name: 'Projects', exact: true });
        const dropdown = page.locator('ul[aria-label="Project pages"]');
        await projects.focus();
        await page.waitForTimeout(100);
        report.interactions.menuBeforeEscape = await dropdown.isVisible();
        await page.keyboard.press('Escape');
        await page.waitForTimeout(100);
        report.interactions.menuAfterEscape = await dropdown.isVisible();
        report.interactions.menuTriggerAttributes = await projects.evaluate(el => ({ expanded: el.getAttribute('aria-expanded'), haspopup: el.getAttribute('aria-haspopup'), controls: el.getAttribute('aria-controls') }));
        const posts = page.locator('header nav').getByRole('link', { name: 'Posts', exact: true });
        await posts.focus();
        await page.keyboard.press('Enter');
        await page.waitForURL('**/posts');
        await page.waitForTimeout(500);
        report.interactions.routeFocus = await page.evaluate(() => ({ tag: document.activeElement.tagName, text: document.activeElement.textContent, mainTabIndex: document.querySelector('main')?.getAttribute('tabindex') }));
      }
    } catch (e) { row.error = e.message; }
    report.results.push(row);
    await fs.writeFile(prefix + '-browser.json', JSON.stringify(report, null, 2) + '\n');
    console.log(JSON.stringify({ width, route, status: row.status, overflow: row.dom && row.dom.documentWidth > width, axe: row.axe?.violations.map(v => ({ id: v.id, count: v.nodes.length })), errors: row.errors, error: row.error }));
    await context.close();
  }
} finally { await browser.close(); }

