import { chromium, devices } from '/home/wsl/repo/rsmb.tv/node_modules/@playwright/test/index.mjs';
import fs from 'node:fs/promises';
const prefix = '/tmp/rsmb-audit-2026-11-10';
const vitalsPath = '/home/wsl/repo/rsmb.tv/node_modules/web-vitals/dist/web-vitals.iife.js';
const vitalsSource = await fs.readFile(vitalsPath, 'utf8');
const manifest = JSON.parse(await fs.readFile('/home/wsl/repo/rsmb.tv/src/content/trips/ocean-shores-2024.json', 'utf8'));
const hero = manifest.photos.find(photo => photo.id === manifest.hero);
const hint = `<link rel="preload" as="image" imagesrcset="${hero.srcSet}" imagesizes="100vw" fetchpriority="high">`;
const browser = await chromium.launch({ headless: true });
const report = { measuredAt: new Date().toISOString(), browser: browser.version(), revision: 'd9cec3d503e6899ee2e798f9fc2629faeb5d06a5', conditions: { cpuSlowdown: 4, latencyMs: 150, downloadMbps: 1.6, uploadMbps: 0.75, device: 'Pixel 7 emulation', cache: 'disabled', analytics: 'blocked', document: 'Both scenarios use intercepted current production HTML; only candidate adds image preload. This affects document TTFB equally.' }, hint, results: [] };
try {
 for (let sample = 1; sample <= 3; sample++) for (const candidate of sample % 2 ? [false, true] : [true, false]) {
  const context = await browser.newContext({ ...devices['Pixel 7'], serviceWorkers: 'block' });
  await context.route(/https:\/\/(?:cloud|gateway)\.umami\.is\//, route => route.abort());
  await context.route('https://www.rsmb.tv/trips/ocean-shores-2024', async route => {
   const response = await route.fetch();
   const html = await response.text();
   await route.fulfill({ response, body: candidate ? html.replace('</head>', hint + '</head>') : html });
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  const cdp = await context.newCDPSession(page);
  const requests = new Map();
  cdp.on('Network.responseReceived', ({ requestId, type, response }) => requests.set(requestId, { url: response.url, type, mimeType: response.mimeType, dataReceivedEncoded: 0, finishedEncoded: null }));
  cdp.on('Network.dataReceived', ({ requestId, encodedDataLength }) => { const row = requests.get(requestId); if (row) row.dataReceivedEncoded += encodedDataLength; });
  cdp.on('Network.loadingFinished', ({ requestId, encodedDataLength }) => { const row = requests.get(requestId); if (row) row.finishedEncoded = encodedDataLength; });
  await cdp.send('Network.enable');
  await cdp.send('Network.setCacheDisabled', { cacheDisabled: true });
  await cdp.send('Network.emulateNetworkConditions', { offline: false, latency: 150, downloadThroughput: 1600000 / 8, uploadThroughput: 750000 / 8 });
  await cdp.send('Emulation.setCPUThrottlingRate', { rate: 4 });
  await page.addInitScript({ content: vitalsSource + '\nwindow.__lcp = null; webVitals.onLCP(metric => window.__lcp = metric.value, { reportAllChanges: true });' });
  await page.goto('https://www.rsmb.tv/trips/ocean-shores-2024', { waitUntil: 'domcontentloaded', timeout: 45000 });
  await page.locator('.trip-hero img').waitFor({ timeout: 30000 });
  await page.waitForFunction(() => { const image = document.querySelector('.trip-hero img'); return image?.complete && image.naturalWidth > 0; }, undefined, { timeout: 45000 });
  await page.waitForTimeout(2000);
  const result = await page.evaluate(() => {
   const hero = document.querySelector('.trip-hero img');
   return { lcp: window.__lcp, heroUrl: hero.currentSrc, resources: performance.getEntriesByType('resource').filter(r => r.name.includes('/assets/') || r.name === hero.currentSrc).map(r => ({ name: r.name, initiatorType: r.initiatorType, startTime: r.startTime, responseEnd: r.responseEnd, encodedBodySize: r.encodedBodySize, decodedBodySize: r.decodedBodySize })) };
  });
  const row = { sample, candidate, ...result, requests: [...requests.values()].filter(r => r.type === 'Script' || r.url === result.heroUrl), errors };
  report.results.push(row);
  await fs.writeFile(prefix + '-hero.json', JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify({ sample, candidate, lcp: row.lcp, hero: row.resources.find(r => r.name === row.heroUrl), errors }));
  await context.close();
 }
} finally { await browser.close(); }

