import { chromium } from '/home/wsl/repo/rsmb.tv/node_modules/@playwright/test/index.mjs';
import fs from 'node:fs/promises';
const browser = await chromium.launch({ headless: true });
const report = { measuredAt: new Date().toISOString(), browser: browser.version(), results: {} };
try {
  const context = await browser.newContext({ reducedMotion: 'reduce', viewport: { width: 390, height: 844 } });
  const page = await context.newPage();
  report.deploymentBefore = await page.request.get('https://www.rsmb.tv/deployment.json').then(r => r.json());
  await context.route(/https:\/\/(?:cloud|gateway)\.umami\.is\//, r => r.abort());
  await page.goto('https://www.rsmb.tv/projects/flights/map');
  const statsToggle = page.getByRole('button', { name: /^(Show|Hide) stats panel$/ });
  await statsToggle.waitFor({ timeout: 30000 });
  await page.locator('a[href="/"]').first().focus();
  report.results.shortcutBefore = await statsToggle.getAttribute('aria-label');
  await page.keyboard.press('s');
  await page.waitForTimeout(300);
  report.results.shortcutAfter = await statsToggle.getAttribute('aria-label');
  report.results.shortcutFocus = await page.evaluate(() => ({ tag: document.activeElement.tagName, href: document.activeElement.getAttribute('href'), text: document.activeElement.textContent }));
  await page.goto('https://www.rsmb.tv/posts?tag=does-not-exist');
  await page.getByText('No posts match these filters.').waitFor();
  report.results.postsEmpty = { text: await page.locator('main').innerText(), resetButtons: await page.getByRole('button', { name: /reset|clear/i }).count() };
  await context.close();

  const stuck = await browser.newContext({ reducedMotion: 'reduce', viewport: { width: 390, height: 844 } });
  const stuckPage = await stuck.newPage();
  const delayed = [];
  let release;
  const gate = new Promise(resolve => { release = resolve; });
  await stuck.route(/https:\/\/.*(?:cartocdn\.com|basemaps\.cartocdn\.com)\//, async route => {
    delayed.push(route.request().url());
    await gate;
    await route.abort().catch(() => {});
  });
  await stuckPage.goto('https://www.rsmb.tv/projects/temperature-records/map');
  await stuckPage.getByTestId('temperature-map').waitFor({ timeout: 30000 });
  await stuckPage.waitForTimeout(18000);
  report.results.temperatureStall = await stuckPage.evaluate(() => ({ state: document.querySelector('[data-testid="temperature-map"]')?.getAttribute('data-map-state'), text: document.body.innerText, alertCount: document.querySelectorAll('[role="alert"]').length, loadingTexts: [...document.querySelectorAll('[role="status"]')].map(el => el.textContent) }));
  report.results.temperatureStall.delayedRequests = delayed.length;
  await stuckPage.screenshot({ path: '/tmp/rsmb-audit-2026-11-10-temperature-stall.png' });
  release();
  await stuckPage.waitForTimeout(2500);
  report.results.temperatureAfterFailure = await stuckPage.evaluate(() => ({ state: document.querySelector('[data-testid="temperature-map"]')?.getAttribute('data-map-state'), text: document.body.innerText, alertCount: document.querySelectorAll('[role="alert"]').length }));
  report.deploymentAfter = await stuckPage.request.get('https://www.rsmb.tv/deployment.json').then(r => r.json());
  await stuck.close();
} catch (e) { report.error = e.message; }
finally {
  await fs.writeFile('/tmp/rsmb-audit-2026-11-10-recovery.json', JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify(report, null, 2));
  await browser.close();
}
